using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize] public class LeadsController(ApplicationDbContext db,AuditService audit):Controller{
 public async Task<IActionResult> Index(string? q){var x=db.Leads.Include(a=>a.Owner).AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))x=x.Where(a=>a.OwnerId==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value);if(!string.IsNullOrWhiteSpace(q))x=x.Where(a=>a.Name.Contains(q)||a.Status.Contains(q));ViewBag.Query=q;return View(await x.OrderByDescending(a=>a.CreatedAt).ToListAsync());}
 public IActionResult Create()=>View(new Lead());
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(Lead m){if(!ModelState.IsValid)return View(m);m.OwnerId=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value;db.Leads.Add(m);await db.SaveChangesAsync();await audit.WriteAsync(User,"Leads","Create",m.Id.ToString(),m.Name);TempData["Success"]="Lead created.";return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>ChangeStatus(int id,string status){var m=await db.Leads.FindAsync(id);if(m==null)return NotFound();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")&&m.OwnerId!=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value)return Forbid();var allowed=new[]{"New","Contacted","Qualified","Unqualified","Converted","Lost"};if(!allowed.Contains(status))return BadRequest();if(m.Status=="Converted"||m.Status=="Lost")return Conflict("Closed leads cannot be changed.");m.Status=status;await db.SaveChangesAsync();await audit.WriteAsync(User,"Leads","StatusChanged",id.ToString(),status);return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Convert(int id){var m=await db.Leads.FindAsync(id);if(m==null)return NotFound();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")&&m.OwnerId!=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value)return Forbid();
 if(m.Status!="Qualified")return BadRequest("Only qualified leads can be converted.");var c=new Customer{Name=m.Name,Email=m.Email,Phone=m.Phone,OwnerId=m.OwnerId};db.Customers.Add(c);m.Status="Converted";m.ConvertedAt=DateTime.UtcNow;await db.SaveChangesAsync();await audit.WriteAsync(User,"Leads","Convert",id.ToString(),$"Customer {c.Id} created");TempData["Success"]="Lead converted to customer.";return RedirectToAction(nameof(Index));}
}
